package migrate

import (
	"database/sql"
	"fmt"
)

// Run adds the orders.status column and backfills it.
//
// It is safe to rerun after a crash at any point: the column is only added
// if missing, only orders without a status are backfilled, and the
// 'backfilled' event is only inserted if the order doesn't already have one.
func Run(db *sql.DB) error {
	if err := addStatusColumn(db); err != nil {
		return fmt.Errorf("add column: %w", err)
	}
	rows, err := db.Query(`SELECT id FROM orders WHERE status IS NULL`)
	if err != nil {
		return err
	}
	var ids []int
	for rows.Next() {
		var id int
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return err
		}
		ids = append(ids, id)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}
	for _, id := range ids {
		if err := backfill(db, id); err != nil {
			return fmt.Errorf("backfill order %d: %w", id, err)
		}
	}
	return nil
}

// addStatusColumn adds orders.status unless a previous run already did.
func addStatusColumn(db *sql.DB) error {
	if _, err := db.Exec(`SELECT status FROM orders LIMIT 0`); err == nil {
		return nil
	}
	_, err := db.Exec(`ALTER TABLE orders ADD COLUMN status TEXT`)
	return err
}

// backfill records the event and sets the status for one order atomically.
// The NOT EXISTS guard covers orders left half-done by runs that predate the
// transaction (event inserted, status still NULL).
func backfill(db *sql.DB, id int) error {
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.Exec(`INSERT INTO order_events (order_id, kind)
		SELECT ?, 'backfilled'
		WHERE NOT EXISTS (SELECT 1 FROM order_events WHERE order_id = ? AND kind = 'backfilled')`, id, id); err != nil {
		return err
	}
	if _, err := tx.Exec(`UPDATE orders SET status = 'open' WHERE id = ?`, id); err != nil {
		return err
	}
	return tx.Commit()
}

