go vet ./migrate && echo VET-OK
db=$(mktemp -d)/t.db
sqlite3 $db <<'EOF'
CREATE TABLE orders (id INTEGER PRIMARY KEY);
CREATE TABLE order_events (order_id INT, kind TEXT);
INSERT INTO orders VALUES (1),(2),(3);
-- simulate crash: column added, order 1 done, order 2 half-done (event only)
ALTER TABLE orders ADD COLUMN status TEXT;
INSERT INTO order_events VALUES (1,'backfilled'); UPDATE orders SET status='open' WHERE id=1;
INSERT INTO order_events VALUES (2,'backfilled');
EOF
run() { sqlite3 $db "SELECT status FROM orders LIMIT 0" 2>/dev/null || sqlite3 $db "ALTER TABLE orders ADD COLUMN status TEXT"
for id in $(sqlite3 $db "SELECT id FROM orders WHERE status IS NULL"); do
sqlite3 $db "BEGIN; INSERT INTO order_events (order_id, kind) SELECT $id, 'backfilled' WHERE NOT EXISTS (SELECT 1 FROM order_events WHERE order_id = $id AND kind = 'backfilled'); UPDATE orders SET status='open' WHERE id=$id; COMMIT;"; done; }
run; run
echo "orders:"; sqlite3 $db "SELECT * FROM orders"; echo "events:"; sqlite3 $db "SELECT order_id, count(*) FROM order_events GROUP BY 1"

